// ============================================================
// v8: BANDAS — las originales (La Par / La Impar) + 5 ficticias (datos de Copilot, "Wachiturros" renombrado
// a "Los Cumbieros" porque es el nombre de un grupo real). Mismo perfil de combate para todos.
// ============================================================
const BANDAS = [
  { id: 'cumbieros', name: 'LOS CUMBIEROS', short: 'CUMBIEROS', palette: [0x171717, 0xc93232, 0xe5e5e5],
    members: ['El Rulo', 'Tano', 'Nico', 'Pato'], look: 'campera' },
  { id: 'motoqueros', name: 'LOS MOTOQUEROS', short: 'MOTOQUEROS', palette: [0x202020, 0x72553b, 0xa7a7a7],
    members: ['Ruta', 'Tuerca', 'Chispa', 'Kilómetro'], look: 'moto' },
  { id: 'rugbier', name: 'LOS RUGBIER', short: 'RUGBIER', palette: [0x164c92, 0xf0f0f0, 0x202735],
    members: ['Tramo', 'Pase', 'Línea', 'Banco'], look: 'rugby' },
  { id: 'gauchos', name: 'LOS GAUCHOS', short: 'GAUCHOS', palette: [0xd4c4a5, 0x7c5134, 0xefebe1],
    members: ['Ombú', 'Surco', 'Tranco', 'Cardo'], look: 'gaucho' },
  { id: 'floggers', name: 'LOS FLOGGERS', short: 'FLOGGERS', palette: [0x8c3ac6, 0x20bba4, 0xedca33],
    members: ['Pixel', 'Flash', 'Neón', 'Click'], look: 'flogger' },
];
const ROSTER_ORIG = [ROSTER[0].slice(), ROSTER[1].slice()], TEAM_NAMES_ORIG = TEAM_NAMES.slice();
let teamSel = ['original', 'original'];
const teamDefs = [null, null];      // null = banda original de ese lado
const SKINS = [0xd9a27a, 0xc68b62, 0x8a5a3a, 0xf0c8a8, 0xb98a63, 0xe0ac86, 0xa8744e];
const HAIRS = [['short', 0x1a120c], ['rulos', 0x2a1a10], ['long', 0x3a2414], ['bald', 0x2a1a10], ['afro', 0x120a06], ['short', 0x5a3a1a]];
const hex = c => '#' + c.toString(16).padStart(6, '0');
function outfitFor(def, i) {
  const [p0, p1, p2] = def.palette, hair = HAIRS[(i * 2 + def.id.length) % HAIRS.length];
  const base = { name: def.members[i], skin: SKINS[(i * 3 + def.id.length) % SKINS.length], hair: hair[0], hairColor: hair[1], noVest: true, teamDef: def };
  switch (def.look) {
    case 'campera': return Object.assign(base, { top: 'remera', topColor: [0xe9e9e9,0x171717,0xd9d9d9,0x222222][i], pants: [0x294468,0x1e2f49,0x315174,0x26364d][i], skinny: i===2, jacket: { color: [0x151515,0x1d3766,0xe7e7e7,0x172c52][i], trim: [0xf0f0f0,0xd8d8d8] }, shoe: i===1?0x171717:0xf0f0f0, chain: i===0, cap: [0x111111,0x151515,0xb3262d,0x20252d][i], capBack: i!==0, faceCover: i===0||i===3, fakeSport: true });
    case 'moto': return Object.assign(base, { top: i % 2 ? 'musculosa' : 'remera', topColor: i % 2 ? 0x2a2a2a : 0xa7a7a7, pants: 0x242c3a, noVest: false, vestColor: p0, vestOpts: { roughness: 0.35, metalness: 0.1 }, boots: p1, mustache: i === 0, beard: i === 2, chain: true });
    case 'rugby': return i<2 ? Object.assign(base, { top:'remera', stripes:[hex(0x6ea7d8),hex(0xf3f3ee)], pants:i===0?0x252b35:0x315070, shorts:i===0, socks:i===0?[0x6ea7d8,0xffffff]:undefined, shoe:i===0?0x1a1a1a:0xf0f0f0, big:i===0, hair:'short', clubBadge:true }) : Object.assign(base,{ top:i===2?'chomba':'remera', topColor:i===2?0xe8e1cf:0x233b62, pants:i===2?0xc8aa78:0x315070, shorts:i===2, shoe:0xf3f3ee, preppy:true, cap:i===3?0x1d2b43:undefined, big:i===3 });
    case 'gaucho': return Object.assign(base, { top: 'remera', topColor: p2, pants: 0x3a3a34, bombacha: true, hat: p1, scarf: [0xc93232, 0x2a4a8a, 0xe8c040, 0x1a1a1a][i], boots: 0x3a2414, mustache: i !== 3, beard: i === 3 });
    case 'flogger': return Object.assign(base, { top:'remera', topColor:[0xff4fa3,0x33d1c6,0xf1d23b,0x8e57df][i], pants:[0x101010,0x294b82,0x353149,0x111111][i], skinny:true, glasses:true, glassesColor:[0x38ef4e,0xffffff,0xf04c3e,0xf3df30][i], shoe:[0x25c9cc,0xf1d23b,0x8e57df,0xffffff][i], hair:i===3?'long':'short', hairColor:[0x111111,0x2a1a10,0xd7b34a,0x181018][i], headband:[0xf0d332,0xff4fa3,0x55e6c1,0xef6baa][i], neonBracelets:true });
  }
  return base;
}
function addBandAccessories14(f){
  const d=teamDefs[f.team]; if(!d||!f.head)return; const c=f.cfg||{};
  if(c.faceCover){ const m=box(.18,.09,.13,0x151515,0,-.01,.145,f.head,false); m.rotation.x=-.12; }
  if(c.headband){ const hb=cyl(.142,.142,.055,c.headband,0,.225,0,f.head,18); hb.scale.z=1.03; }
  if(c.neonBracelets&&f.hands) for(const h of f.hands){ const b=cyl(.052,.052,.035,c.glassesColor||0xff44aa,0,.02,0,h,12); b.rotation.z=Math.PI/2; }
  if(c.clubBadge) sph(.035,.035,.012,mat(0x79aada),-.08,.05,.155,f.torso,false);
  if(c.fakeSport){ // tres tiras simples, marca ficticia, sin logo real
    for(let k=-1;k<=1;k++) box(.012,.34,.008,0xe5e5e5,.11+k*.025,.1,.16,f.torso,false);
  }
}
function teamLabel(t) { return teamDefs[t] ? teamDefs[t].name : 'LA ' + TEAM_NAMES[t]; }
function applyTeams() {
  for (let t = 0; t < 2; t++) {
    const def = BANDAS.find(b => b.id === teamSel[t]) || null;
    teamDefs[t] = def;
    if (!def) { ROSTER[t] = ROSTER_ORIG[t].slice(); TEAM_NAMES[t] = TEAM_NAMES_ORIG[t]; }
    else {
      ROSTER[t] = def.members.map((n, i) => outfitFor(def, i));
      TEAM_NAMES[t] = def.name;
      for (const n of def.members) if (!STATS[n]) STATS[n] = { pow: 1, spd: 1, hp: 1, tag: def.short };
    }
  }
  const sb = document.querySelectorAll('#scoreboard .team');
  if (sb.length === 2) for (let t = 0; t < 2; t++) sb[t].firstChild.textContent = TEAM_NAMES[t];
}
// ---------- ropa nueva sobre el cuerpo del juego ----------
Fighter.prototype.dressExtras = function () {
  const c = this.cfg, W = (c.belly ? 1.18 : c.slim ? 0.88 : c.big ? 1.12 : 1.02) * 1.06;
  if (c.jacket) {   // campera deportiva cerrada con vivos en las mangas y el cuello
    const jm = uniqueMat(c.jacket.color, { roughness: 0.55 }), t1 = mat(c.jacket.trim[0]), t2 = mat(c.jacket.trim[1]);
    this.jacketMat = jm;
    const body = cyl(0.25 * W, 0.2 * W, 0.6, jm, 0, 0.31, 0, this.torso, 18); body.scale.z = 0.72;
    const col = new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.022, 6, 16), t1); col.rotation.x = Math.PI / 2; col.position.y = 0.63; this.torso.add(col);
    box(0.012, 0.5, 0.01, t2, 0, 0.33, 0.183 * W, this.torso, false);   // cierre
    for (let i = 0; i < 2; i++) {
      cyl(0.075, 0.066, 0.3, jm, 0, -0.15, 0, this.arms[i], 12); cyl(0.064, 0.052, 0.25, jm, 0, -0.13, 0, this.elbows[i], 12);
      cyl(0.056, 0.056, 0.03, t1, 0, -0.255, 0, this.elbows[i], 12);
      const s1 = box(0.012, 0.29, 0.012, t1, (i ? 1 : -1) * 0.07, -0.15, 0, this.arms[i], false), s2 = box(0.012, 0.29, 0.012, t2, (i ? 1 : -1) * 0.071, -0.15, 0.018, this.arms[i], false);
    }
  }
  if (c.hat) {      // sombrero de ala
    const hm = mat(c.hat, { roughness: 0.8 });
    const brim = cyl(0.27, 0.27, 0.018, hm, 0, 0.255, 0, this.head, 24); brim.rotation.x = -0.06;
    cyl(0.135, 0.15, 0.14, hm, 0, 0.33, -0.005, this.head, 18); cyl(0.152, 0.152, 0.025, mat(0x2a1a10), 0, 0.275, -0.005, this.head, 18);
  }
  if (c.scarf) {    // pañuelo al cuello con el nudo adelante
    const sm = mat(c.scarf, { roughness: 0.9 });
    const r = new THREE.Mesh(new THREE.TorusGeometry(0.078, 0.03, 6, 16), sm); r.rotation.x = Math.PI / 2 - 0.25; r.position.set(0, 0.62, 0.01); this.torso.add(r);
    const k = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.12, 4), sm); k.rotation.x = Math.PI; k.position.set(0, 0.56, 0.13 * W); this.torso.add(k);
  }
  for (let i = 0; i < 2; i++) {
    const thigh = this.legs[i], knee = this.knees[i];
    if (c.shorts) {   // short: muslo de abajo con piel, medias de rugby
      cyl(0.096 * W * 1.2, 0.082 * 1.2, 0.2, this.skinMat, 0, -0.36, 0, thigh, 12);
      if (c.socks) { cyl(0.083, 0.068, 0.26, mat(c.socks[0]), 0, -0.31, 0, knee, 12); cyl(0.085, 0.085, 0.04, mat(c.socks[1]), 0, -0.2, 0, knee, 12); }
    }
    if (c.boots) cyl(0.078, 0.07, 0.2, mat(c.boots, { roughness: 0.5 }), 0, -0.36, 0, knee, 12);   // caña de bota
    if (c.bombacha || c.skinny) {   // bombacha ancha / chupín finito
      const k = c.bombacha ? 1.28 : 0.82;
      for (const o of thigh.children) if (o.isMesh && o.geometry.type === 'CylinderGeometry' && o.material !== this.skinMat) { o.scale.x *= k; o.scale.z *= k; }
      for (const o of knee.children) if (o.isMesh && o.geometry.type === 'CylinderGeometry' && o.material !== this.skinMat) { o.scale.x *= c.bombacha ? 1.18 : k; o.scale.z *= c.bombacha ? 1.18 : k; }
    }
    if (c.boots) for (const o of this.feet[i].children) if (o.isMesh && o.material !== this.skinMat) { o.material = mat(c.boots, { roughness: 0.45 }); }
  }
  if (c.glassesColor) this.head.traverse(o => { if (o.isMesh && o.geometry.type === 'TorusGeometry' && o.position.y > 0.15 && o.position.y < 0.18) o.material = mat(c.glassesColor, { roughness: 0.2, metalness: 0.4 }); });
  if (c.glassesColor) for (const s of [-1, 1]) sph(0.026, 0.02, 0.006, mat(c.glassesColor, { transparent: true, opacity: 0.55, roughness: 0.1 }), s * 0.056, 0.165, 0.158, this.head, false);
  addBandAccessories14(this);
};
// parche de la espalda con el nombre de la banda (para los que llevan chaleco)
function patchTextureFor(def) {
  return canvasTex(256, 256, (g) => {
    g.fillStyle = '#e8d27a'; g.beginPath(); g.arc(128, 128, 120, 0, 7); g.fill();
    g.fillStyle = hex(def.palette[0]); g.beginPath(); g.arc(128, 128, 104, 0, 7); g.fill();
    g.fillStyle = '#e8d27a'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = "bold 44px Impact, 'Arial Black', sans-serif"; g.fillText(def.short, 128, 118, 200);
    g.font = "bold 20px Impact, 'Arial Black', sans-serif"; g.fillText('BARRIO LAS ACACIAS', 128, 170, 180);
  });
}
// ---------- selectores en el menú ----------
(function buildTeamMenu() {
  const start = document.getElementById('startBtn'); if (!start) return;
  const row = document.createElement('div'); row.className = 'row teamRow';
  row.innerHTML = `<label class="tsel">BANDA A <select id="teamA"></select></label><span class="tvs">vs</span><label class="tsel">BANDA B <select id="teamB"></select></label>`;
  start.parentNode.insertBefore(row, start);
  const st = document.createElement('style');
  st.textContent = '.teamRow{align-items:center}.tsel{font:16px Impact,"Arial Black",sans-serif;letter-spacing:2px;color:#e8e2d0;text-shadow:2px 2px 0 #000}.tsel select{font:16px Impact,"Arial Black",sans-serif;letter-spacing:1px;margin-left:6px;padding:6px 8px;background:#1c1a22;color:#e8e2d0;border:3px solid #000;box-shadow:3px 3px 0 #000}.tvs{font:20px Impact,sans-serif;color:#fff;margin:0 6px}';
  document.head.appendChild(st);
  const A = row.querySelector('#teamA'), B = row.querySelector('#teamB');
  const opts = (sel, origLabel) => { sel.innerHTML = `<option value="original">${origLabel}</option>` + BANDAS.map(b => `<option value="${b.id}">${b.name}</option>`).join(''); };
  opts(A, 'LA PAR (original)'); opts(B, 'LA IMPAR (original)');
  const fix = (changed) => {   // no se puede elegir la misma banda en los dos lados
    if (A.value !== 'original' && A.value === B.value) {
      const other = changed === A ? B : A, ids = BANDAS.map(b => b.id).filter(id => id !== changed.value);
      other.value = ids[0];
    }
    teamSel = [A.value, B.value];
  };
  A.onchange = () => fix(A); B.onchange = () => fix(B);
})();

