const ARSENAL = {
  original: ['escape', 'cuchillo', 'palo', 'llave'],
  cumbieros: ['escape', 'llave', 'cuchillo', 'botella'],
  motoqueros: ['cadena', 'botella', 'llave', 'cuchillo'],
  rugbier: ['pelota', 'mancuerna', 'botella', 'palo'],
  gauchos: ['rebenque', 'alambre', 'facon', 'boleadoras'],
  floggers: ['skate', 'paraguas', 'botella', 'cuchillo'],
};
function arsenalFor(t) { return ARSENAL[teamDefs[t] ? teamDefs[t].id : 'original'].slice(); }
// cambia las cartas, los íconos y las armas de la mesa de la casa según la banda A
const PICK_LINES_V9 = {
  rebenque: ['Con esto arreo a cualquiera.', 'El rebenque del abuelo.'], alambre: ['Del alambrado de la quinta.', 'Esto engancha lindo.'],
  facon: ['El facón no se presta.', 'Con cuidado, que corta.'], boleadoras: ['Se las tiro a las patas.', 'Como en el campo.'],
  cadena: ['La cadena de la moto.', 'Esta llega lejos.'], mancuerna: ['De la sala de pesas del club.', 'Pesa una banda.'],
  pelota: ['Va de puntín.', 'Un try en la cabeza.'], skate: ['Tabla y a la cabeza.', 'Con lija y todo.'],
  paraguas: ['Por si llueve... golpes.', 'Lo tengo de adorno.'], botella: ['Para tomar o para tirar.', 'Vacía, pero sirve.'],
};
function applyArsenal() {
  LOADOUT_KEYS = arsenalFor(0);
  for (const k in PICK_LINES_V9) if (!PICK_LINES[k]) PICK_LINES[k] = PICK_LINES_V9[k];
  if (LOADOUT_KEYS.some(k => !ICONS[k])) renderIcons();
  for (const k in tableWeapons) { if (tableWeapons[k].parent) tableWeapons[k].parent.remove(tableWeapons[k]); delete tableWeapons[k]; }
  LOADOUT_KEYS.forEach((k, i) => {
    const w = makeWeaponMesh(k); w.rotation.order = 'YXZ'; w.rotation.set(Math.PI / 2, rand(-0.15, 0.15), 0);
    w.position.set(-0.6 + i * 0.4, 0.76 + WEAPONS[k].gy * WEAPON_SCALE, 0.45); tableGroup.add(w); tableWeapons[k] = w;
  });
}
{
  const base = applyTeams;
  applyTeams = function () { base(); applyArsenal(); };
}

